-- Read-only compatibility probe for bcryptjs $2b$ hashes.
-- Run against the intended local Supabase/PostgreSQL instance with:
--   psql "postgresql://postgres:postgres@127.0.0.1:54322/postgres" -v ON_ERROR_STOP=1 -f supabase/pin-bcrypt-compatibility-check.sql
-- The hash below was generated by bcryptjs at 10 rounds for the synthetic PIN 0427.
-- This script does not create extensions or modify database objects/data.
DO $check_bcrypt_compatibility$
DECLARE
  crypto_schema text;
  accepted boolean;
  rejected boolean;
  synthetic_hash constant text := '$2b$10$wF6.BP93I1SqZcvkRxbOC.hlc9SZ7CLhGVxb2BTUYrj1aBGhCiFd.';
BEGIN
  SELECT n.nspname
    INTO crypto_schema
    FROM pg_catalog.pg_proc AS p
    JOIN pg_catalog.pg_namespace AS n ON n.oid = p.pronamespace
    WHERE p.proname = 'crypt'
      AND p.proargtypes = '25 25'::pg_catalog.oidvector
      AND n.nspname IN ('extensions', 'public')
    ORDER BY CASE n.nspname WHEN 'extensions' THEN 0 ELSE 1 END
    LIMIT 1;

  IF crypto_schema IS NULL THEN
    RAISE EXCEPTION 'BLOCKED: pgcrypto crypt(text,text) is not installed in extensions or public';
  END IF;

  EXECUTE pg_catalog.format(
    'SELECT %I.crypt($1, $2) = $2, %I.crypt($3, $2) <> $2',
    crypto_schema,
    crypto_schema
  )
  INTO accepted, rejected
  USING '0427', synthetic_hash, '0428';

  IF accepted IS DISTINCT FROM true OR rejected IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'BLOCKED: PostgreSQL crypt did not match bcryptjs $2b$ correct/wrong PIN behavior';
  END IF;

  RAISE NOTICE 'PASS: PostgreSQL crypt accepted the synthetic bcryptjs $2b$ PIN and rejected a wrong PIN';
END;
$check_bcrypt_compatibility$;
